'use strict';
const icons = {
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
  heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
  bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',
  user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  'chevron-down':'<path d="m6 9 6 6 6-6"/>',
  'arrow-right':'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  'arrow-left':'<path d="M20 12H4m6-6-6 6 6 6"/>',
  'arrow-up':'<path d="M12 20V4m-6 6 6-6 6 6"/>',
  'arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>',
  layers:'<path d="m12 3 10 6-10 6L2 9l10-6ZM2 13l10 6 10-6M2 17l10 6 10-6"/>',
  truck:'<path d="M1 5h13v12H1V5ZM14 9h4l4 4v4h-8"/><circle cx="5" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
  shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',
  x:'<path d="m6 6 12 12M18 6 6 18"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  minus:'<path d="M5 12h14"/>',
  check:'<path d="m5 12 4 4L19 6"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons['arrow-right']}</svg>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
const $ = selector => document.querySelector(selector);
const escapeHTML = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(value);
const colors={rose:{name:'Hồng phấn',hex:'#c87695',asset:'mat-rose.svg'},plum:{name:'Đỏ rượu',hex:'#8b3055',asset:'mat-plum.svg'},sage:{name:'Xanh sage',hex:'#8f9c84',asset:'mat-sage.svg'},cacao:{name:'Nâu cacao',hex:'#8c685a',asset:'mat-cacao.svg'},sand:{name:'Be cát',hex:'#c3ad8e',asset:'mat-sand.svg'},lavender:{name:'Tím nhạt',hex:'#9f8baa',asset:'mat-lavender.svg'}};
const products=[
 {id:'lilium',name:'Thảm cao su Lilium',group:'rubber',type:'Thảm cao su',price:670000,old:699000,color:'plum',badge:'Từ bản thiết kế',size:'183 × 68 cm · 4 mm',description:'Tên dòng Lilium và mức giá được lấy từ thiết kế. Hình, kích thước và lựa chọn màu trong bản thử là minh họa, cần đối chiếu sản phẩm thật.'},
 {id:'rubber-rose',name:'Thảm cao su · Hồng phấn',group:'rubber',type:'Thảm cao su',price:670000,color:'rose',badge:'Sản phẩm mẫu',size:'183 × 68 cm · 4 mm',description:'Mẫu thảm cao su để trải nghiệm lựa chọn màu, xem chi tiết và thêm vào giỏ. Thông tin chưa phải mô tả của một sản phẩm đang bán.'},
 {id:'rubber-sage',name:'Thảm cao su · Xanh sage',group:'rubber',type:'Thảm cao su',price:670000,color:'sage',badge:'Sản phẩm mẫu',size:'183 × 68 cm · 4 mm',description:'Một lựa chọn minh họa trong nhóm thảm cao su. Dùng để kiểm tra cách bộ lọc, giỏ hàng và lựa chọn màu hoạt động.'},
 {id:'tpe-rose',name:'Thảm TPE · Hồng phấn',group:'tpe',type:'Thảm TPE',price:420000,color:'rose',badge:'Sản phẩm mẫu',size:'183 × 61 cm · 6 mm',description:'Mẫu thảm TPE dành cho bản trải nghiệm. Giá, màu sắc, kích thước và hình ảnh sẽ cần thay bằng dữ liệu thật.'},
 {id:'tpe-lavender',name:'Thảm TPE · Tím nhạt',group:'tpe',type:'Thảm TPE',price:420000,color:'lavender',badge:'Sản phẩm mẫu',size:'183 × 61 cm · 6 mm',description:'Mẫu thứ hai của nhóm TPE, giúp kiểm tra trải nghiệm so sánh và sắp xếp giá trong danh mục.'},
 {id:'premium-cacao',name:'Thảm cao cấp · Cacao',group:'premium',type:'Thảm cao cấp',price:890000,color:'cacao',badge:'Sản phẩm mẫu',size:'183 × 68 cm · 5 mm',description:'Mẫu thảm ở phân khúc giá cao hơn, phục vụ kiểm tra phân nhóm trong thiết kế. Chưa có thông số hoặc chứng nhận vật liệu thực tế.'},
 {id:'block',name:'Gạch tập yoga',group:'accessory',type:'Phụ kiện',price:180000,asset:'block.svg',colorName:'Be tự nhiên',colorHex:'#be9a73',size:'23 × 15 × 7,5 cm',badge:'Sản phẩm mẫu'},
 {id:'strap',name:'Dây hỗ trợ tập yoga',group:'accessory',type:'Phụ kiện',price:120000,asset:'strap.svg',colorName:'Hồng phấn',colorHex:'#c87695',size:'Dài 250 cm',badge:'Sản phẩm mẫu'},
 {id:'bag',name:'Túi đựng thảm yoga',group:'accessory',type:'Phụ kiện',price:250000,asset:'bag.svg',colorName:'Đỏ rượu',colorHex:'#8b3055',size:'Dài 72 cm',badge:'Sản phẩm mẫu'},
 {id:'towel',name:'Khăn trải thảm yoga',group:'accessory',type:'Phụ kiện',price:290000,asset:'towel.svg',colorName:'Xanh sage',colorHex:'#8f9c84',size:'183 × 61 cm',badge:'Sản phẩm mẫu'},
 {id:'wheel',name:'Vòng hỗ trợ yoga',group:'accessory',type:'Phụ kiện',price:320000,asset:'wheel.svg',colorName:'Hồng phấn',colorHex:'#c87695',size:'Đường kính 32 cm',badge:'Sản phẩm mẫu'},
 {id:'roller',name:'Con lăn hỗ trợ tập',group:'accessory',type:'Phụ kiện',price:260000,asset:'roller.svg',colorName:'Tím nhạt',colorHex:'#9f8baa',size:'Dài 33 cm',badge:'Sản phẩm mẫu'},
 {id:'ball',name:'Bóng hỗ trợ tập yoga',group:'accessory',type:'Phụ kiện',price:210000,asset:'ball.svg',colorName:'Hồng phấn',colorHex:'#c87695',size:'Đường kính 65 cm',badge:'Sản phẩm mẫu'},
 {id:'pouch',name:'Túi phụ kiện yoga',group:'accessory',type:'Phụ kiện',price:150000,asset:'pouch.svg',colorName:'Be cát',colorHex:'#c3ad8e',size:'26 × 18 cm',badge:'Sản phẩm mẫu'}
];
const findProduct = id=>products.find(p=>p.id===id);
const imageFor=(p,color=p.color)=>`assets/${p.asset || colors[color]?.asset || colors.rose.asset}`;
const colorName=(p,color=p.color)=>p.colorName || colors[color]?.name || '';
const colorHex=(p,color=p.color)=>p.colorHex || colors[color]?.hex || '#c87695';
const STORAGE=new URLSearchParams(location.search).has('qa')?'louis-yoga-prototype-qa-v1':'louis-yoga-prototype-v1';
let storageAvailable=true;
function loadState(){try{const s=JSON.parse(localStorage.getItem(STORAGE)||'{}');return {cart:Array.isArray(s.cart)?s.cart.filter(i=>findProduct(i.id)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=10&&(!findProduct(i.id).color||colors[i.color])):[],favorites:Array.isArray(s.favorites)?s.favorites.filter(id=>findProduct(id)):[],orders:Array.isArray(s.orders)?s.orders.slice(-30):[],interests:Array.isArray(s.interests)?s.interests.slice(-30):[],newsletter:Array.isArray(s.newsletter)?s.newsletter.slice(-30):[]};}catch{storageAvailable=false;return {cart:[],favorites:[],orders:[],interests:[],newsletter:[]};}}
let state=loadState();
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{storageAvailable=false;toast('Trình duyệt không lưu được dữ liệu; bản thử vẫn hoạt động trong phiên này.');}}
let filter='all',sort='featured',accessoryPage=0,detailProduct=null,detailColor=null,detailQty=1,quizStep=0,quizAnswers=[];
let toastTimer,focusBeforeModal,focusBeforeDrawer;
const modal=$('#modal');
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3700);}
function countCart(){return state.cart.reduce((n,i)=>n+i.qty,0);}
function totalCart(){return state.cart.reduce((n,i)=>n+findProduct(i.id).price*i.qty,0);}
function updateCounts(){for(const [id,n] of [['#cart-count',countCart()],['#favorite-count',state.favorites.length]]){$(id).textContent=n;$(id).hidden=n===0;}}
function card(p){return `<article class="product-card"><button class="product-image-button" data-action="detail" data-id="${p.id}" aria-label="Xem ${p.name}"><img src="${imageFor(p)}" alt="Minh họa ${p.name}" width="420" height="350"><span class="product-badge">${p.badge}</span></button><button class="favorite-button" data-action="favorite" data-id="${p.id}" aria-label="Yêu thích ${p.name}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button><div class="product-info"><span class="product-type">${p.type}</span><button class="product-title" data-action="detail" data-id="${p.id}">${p.name}</button><span class="product-color"><i class="color-dot" style="background:${colorHex(p)}"></i>${colorName(p)}</span><div class="product-price"><strong>${money(p.price)}</strong>${p.old?`<del>${money(p.old)}</del>`:''}</div><div class="card-actions"><button class="add-button" data-action="add" data-id="${p.id}">Thêm vào giỏ</button><button class="buy-button" data-action="buy" data-id="${p.id}">Mua thử</button></div></div></article>`;}
function renderMats(){let list=products.filter(p=>p.group!=='accessory'&&(filter==='all'||p.group===filter));if(sort==='asc')list.sort((a,b)=>a.price-b.price);if(sort==='desc')list.sort((a,b)=>b.price-a.price);$('#mat-products').innerHTML=list.map(card).join('');$('#mat-count').textContent=`${list.length} sản phẩm mẫu · Giá & thông số dùng để thử giao diện`;document.querySelectorAll('[data-filter]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.filter===filter));b.tabIndex=b.dataset.filter===filter?0:-1;});}
function setFilter(value){filter=value;renderMats();}
function renderAccessories(){const list=products.filter(p=>p.group==='accessory');$('#accessory-products').innerHTML=list.slice(accessoryPage*4,accessoryPage*4+4).map(card).join('');$('#accessory-pagination').innerHTML=[0,1].map(n=>`<button data-action="accessory-page" data-page="${n}" class="${n===accessoryPage?'active':''}" aria-label="Nhóm phụ kiện ${n+1}" aria-current="${n===accessoryPage?'true':'false'}"></button>`).join('')+`<span>${accessoryPage+1} / 2</span>`;}
function renderFavoritesState(){document.querySelectorAll('[data-action=favorite]').forEach(b=>b.setAttribute('aria-pressed',String(state.favorites.includes(b.dataset.id))));updateCounts();}
function favorite(id){if(state.favorites.includes(id)){state.favorites=state.favorites.filter(v=>v!==id);toast('Đã bỏ khỏi danh sách yêu thích.');}else{state.favorites.push(id);toast('Đã lưu sản phẩm yêu thích.');}save();renderFavoritesState();if(modal.open&&modal.dataset.view==='favorites')showFavorites();}
function addToCart(id,color,qty=1,notify=true){const p=findProduct(id);if(!p)return false;color=p.color?(color||p.color):'default';const key=`${id}:${color}`;const item=state.cart.find(i=>i.key===key);if((item?.qty||0)+qty>10){toast('Bản thử cho phép tối đa 10 sản phẩm mỗi lựa chọn.');return false;}if(item)item.qty+=qty;else state.cart.push({id,color,qty,key});save();updateCounts();if(!$('#cart-drawer').hidden)renderCart();if(notify)toast('Đã thêm vào giỏ hàng.');return true;}
function lockPage(){document.body.classList.toggle('locked',modal.open||!$('#cart-drawer').hidden);}
function openModal(kicker,html,view){if(!modal.open){focusBeforeModal=document.activeElement;}$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=html;modal.dataset.view=view||'';hydrateIcons(modal);if(!modal.open)modal.showModal();modal.scrollTop=0;lockPage();}
function closeModal(){if(modal.open)modal.close();}
modal.addEventListener('close',()=>{lockPage();if(focusBeforeModal?.isConnected)focusBeforeModal.focus({preventScroll:true});});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const inertTargets=()=>[...document.body.children].filter(e=>!['modal','cart-drawer','drawer-backdrop','toast'].includes(e.id)&&e.tagName!=='SCRIPT');
function openCart(){closeModal();focusBeforeDrawer=document.activeElement;$('#cart-drawer').hidden=false;$('#drawer-backdrop').hidden=false;inertTargets().forEach(e=>e.inert=true);renderCart();lockPage();$('#cart-drawer [data-action=close-cart]').focus();}
function closeCart(){if($('#cart-drawer').hidden)return;$('#cart-drawer').hidden=true;$('#drawer-backdrop').hidden=true;inertTargets().forEach(e=>e.inert=false);lockPage();if(focusBeforeDrawer?.isConnected)focusBeforeDrawer.focus({preventScroll:true});}
$('#drawer-backdrop').addEventListener('click',closeCart);
function renderCart(){$('#drawer-count').textContent=countCart();if(!state.cart.length){$('#cart-content').innerHTML=`<div class="empty-state"><span data-icon="bag"></span><h3>Giỏ hàng còn trống</h3><p>Khám phá thảm và phụ kiện, rồi thử thêm món bạn thích.</p><button class="button button-pink" data-action="continue-shopping">Khám phá sản phẩm ${icon('arrow-right')}</button></div>`;$('#cart-footer').innerHTML='';}else{$('#cart-content').innerHTML=state.cart.map(i=>{const p=findProduct(i.id);return `<article class="cart-item"><img src="${imageFor(p,i.color)}" alt="Minh họa ${p.name}"><div><h3>${p.name}</h3><p>${colorName(p,i.color)}</p><strong>${money(p.price)}</strong><div class="cart-item-controls"><div class="qty-stepper"><button data-action="cart-minus" data-key="${i.key}" aria-label="Giảm số lượng ${p.name}" ${i.qty===1?'disabled':''}>${icon('minus')}</button><span>${i.qty}</span><button data-action="cart-plus" data-key="${i.key}" aria-label="Tăng số lượng ${p.name}" ${i.qty===10?'disabled':''}>${icon('plus')}</button></div><button class="remove-button" data-action="remove" data-key="${i.key}">Xóa</button></div></div></article>`;}).join('');$('#cart-footer').innerHTML=`<div class="cart-total"><span>Tạm tính</span><strong>${money(totalCart())}</strong></div><p>Chưa tính phí giao hàng. Mọi giá trị là dữ liệu thử.</p><button class="button button-pink" data-action="checkout">Tiếp tục đặt hàng thử ${icon('arrow-right')}</button><p style="margin-top:10px">Không thu tiền · Không gửi đơn đến Louis Yoga</p>`;}hydrateIcons($('#cart-drawer'));}
function cartQty(key,delta){const item=state.cart.find(i=>i.key===key);if(!item)return;item.qty=Math.max(1,Math.min(10,item.qty+delta));save();updateCounts();renderCart();}
function showDetail(id){detailProduct=findProduct(id);if(!detailProduct)return;detailColor=detailProduct.color;detailQty=1;renderDetail();}
function renderDetail(){const p=detailProduct;const isMat=p.group!=='accessory';openModal('BỘ SƯU TẬP · DỮ LIỆU MẪU',`<div class="detail-layout"><div class="detail-image"><img src="${imageFor(p,detailColor)}" alt="Minh họa ${p.name}" width="420" height="350"></div><div class="detail-info"><span class="eyebrow">${p.type}</span><h2 id="modal-title">${p.name}</h2><div class="detail-price">${money(p.price)}${p.old?`<del>${money(p.old)}</del>`:''}</div><p>${p.description||'Phụ kiện minh họa để kiểm tra danh mục và trải nghiệm mua. Giá, hình ảnh và thông số cần thay bằng dữ liệu sản phẩm thật.'}</p><p style="margin-bottom:4px">Màu: <strong>${colorName(p,detailColor)}</strong></p>${isMat?`<div class="color-choices">${['rose','plum','sage','cacao','lavender'].map(c=>`<button class="color-choice ${c===detailColor?'selected':''}" style="--swatch:${colors[c].hex}" data-action="detail-color" data-color="${c}" aria-label="Chọn màu ${colors[c].name}" aria-pressed="${c===detailColor}"></button>`).join('')}</div>`:''}<div class="detail-controls"><div class="qty-stepper"><button data-action="detail-minus" aria-label="Giảm số lượng" ${detailQty===1?'disabled':''}>${icon('minus')}</button><span>${detailQty}</span><button data-action="detail-plus" aria-label="Tăng số lượng" ${detailQty===10?'disabled':''}>${icon('plus')}</button></div><button class="button button-outline" data-action="detail-add">Thêm vào giỏ ${icon('bag')}</button></div><button class="button button-pink detail-buy" data-action="detail-buy">Mua thử ngay ${icon('arrow-right')}</button></div></div><div class="detail-specs"><div class="demo-notice">Hình & thông số là minh họa. Bản thử chưa kết nối kho hàng, thanh toán hoặc đánh giá khách hàng thật.</div><table class="spec-table"><tbody><tr><td>Kích thước minh họa</td><td>${p.size}</td></tr><tr><td>Màu đang chọn</td><td>${colorName(p,detailColor)}</td></tr><tr><td>Chính sách bảo hành</td><td>Chờ bổ sung chính sách được duyệt</td></tr></tbody></table></div>`,'detail');}
function showFavorites(){const list=products.filter(p=>state.favorites.includes(p.id));openModal('LƯU CHO LẦN SAU',`<div class="modal-body-pad"><h2 id="modal-title">Sản phẩm yêu thích</h2><p>Lựa chọn được lưu riêng trên trình duyệt này.</p>${list.length?`<div class="product-grid favorites-grid">${list.map(card).join('')}</div>`:`<div class="empty-state"><span data-icon="heart"></span><h3>Chưa có sản phẩm yêu thích</h3><p>Bấm biểu tượng trái tim trên một sản phẩm để lưu tại đây.</p><button class="button button-pink" data-action="continue-shopping">Xem bộ sưu tập</button></div>`}</div>`,'favorites');}
function normalize(text){return text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function showSearch(){openModal('KHÁM PHÁ BỘ SƯU TẬP',`<div class="modal-body-pad"><h2 id="modal-title">Bạn đang tìm gì?</h2><label class="search-field"><span data-icon="search"></span><input id="search-input" type="search" autocomplete="off" placeholder="Thử: thảm cao su, TPE, dây tập…" aria-label="Tìm theo tên, chất liệu hoặc màu"></label><div id="search-results"></div></div>`,'search');searchProducts('');$('#search-input').focus();}
function searchProducts(query){const q=normalize(query.trim());const list=products.filter(p=>normalize(`${p.name} ${p.type} ${colorName(p)}`).includes(q));$('#search-results').innerHTML=`<div class="search-count" role="status">${list.length} sản phẩm${q?' phù hợp':''}</div>${list.length?`<div class="search-results">${list.map(p=>`<button class="search-result" data-action="detail" data-id="${p.id}"><img src="${imageFor(p)}" alt="Minh họa ${p.name}"><span><b>${p.name}</b><small>${money(p.price)}</small></span></button>`).join('')}</div>`:'<div class="empty-state"><h3>Chưa tìm thấy sản phẩm</h3><p>Thử từ khóa ngắn hơn như “thảm”, “TPE” hoặc “túi”.</p></div>'}`;}
function showCheckout(){if(!state.cart.length){toast('Thêm sản phẩm vào giỏ trước khi đặt hàng thử.');return;}closeCart();closeModal();openModal('BƯỚC CUỐI · ĐẶT HÀNG MÔ PHỎNG',`<div class="modal-body-pad"><h2 id="modal-title">Thử đặt hàng</h2><div class="demo-notice">Không phát sinh thanh toán và không gửi đơn đến Louis Yoga. Anh có thể nhập dữ liệu giả để thử. Thông tin chỉ lưu trên trình duyệt này.</div><div class="order-summary">${state.cart.map(i=>`<div><span>${findProduct(i.id).name} · ${colorName(findProduct(i.id),i.color)} × ${i.qty}</span><strong>${money(findProduct(i.id).price*i.qty)}</strong></div>`).join('')}<div><span>Tạm tính · Chưa có phí giao hàng</span><strong>${money(totalCart())}</strong></div></div><form id="checkout-form"><div class="form-grid"><label class="field">Tên người nhận *<input name="name" required maxlength="80" autocomplete="name" placeholder="Ví dụ: Nguyễn Văn A"></label><label class="field">Số điện thoại *<input name="phone" type="tel" required inputmode="tel" maxlength="20" autocomplete="tel" placeholder="Ví dụ: 0901234567"></label><label class="field wide">Địa chỉ giao hàng *<textarea name="address" required maxlength="250" autocomplete="street-address" placeholder="Nhập một địa chỉ để thử luồng đặt hàng"></textarea></label><label class="field wide">Ghi chú<input name="note" maxlength="200" placeholder="Ghi chú cho đơn thử (không bắt buộc)"></label></div><label class="check-field"><input name="consent" type="checkbox" required><span>Tôi hiểu đây là đơn mô phỏng, không phải đơn mua hàng thật.</span></label><p id="checkout-error" class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="button button-outline" data-action="cart">Quay lại giỏ</button><button type="submit" class="button button-pink">Tạo đơn hàng thử ${icon('arrow-right')}</button></div></form></div>`,'checkout');}
function handleCheckout(form){const fd=new FormData(form);const name=String(fd.get('name')||'').trim(),address=String(fd.get('address')||'').trim(),phone=String(fd.get('phone')||'').trim();const compact=phone.replace(/[\s().-]/g,'');if(!name||!address){$('#checkout-error').textContent='Vui lòng nhập tên và địa chỉ có nội dung.';return;}if(!/^(0\d{9}|\+84\d{9})$/.test(compact)){$('#checkout-error').textContent='Nhập số Việt Nam gồm 10 chữ số bắt đầu bằng 0, hoặc +84 và 9 chữ số.';form.elements.phone.focus();return;}if(!state.cart.length){$('#checkout-error').textContent='Giỏ hàng đã trống. Hãy chọn lại sản phẩm.';return;}const id=`LY-DEMO-${Date.now().toString(36).toUpperCase()}`;const order={id,date:new Date().toISOString(),name,phone,address,note:String(fd.get('note')||'').trim(),items:state.cart.map(i=>({...i})),total:totalCart()};state.orders.push(order);state.orders=state.orders.slice(-30);state.cart=[];save();updateCounts();openModal('ĐƠN HÀNG MÔ PHỎNG',`<div class="success-view"><span class="success-icon">${icon('check')}</span><h2 id="modal-title">Đã tạo đơn hàng thử</h2><p>Luồng mua đã hoàn tất. Đơn này chỉ được lưu trên trình duyệt của bạn.</p><div class="order-ticket"><p><strong>Mã đơn:</strong> ${id}</p><p><strong>Người nhận:</strong> ${escapeHTML(name)}</p><p><strong>Tạm tính:</strong> ${money(order.total)}</p><p><strong>Trạng thái:</strong> Mô phỏng · Không xử lý giao hàng</p></div><button class="button button-pink" data-action="orders">Xem đơn hàng thử ${icon('arrow-right')}</button><p style="margin-top:15px">Không thu tiền và không gửi thông tin ra bên ngoài.</p></div>`,'success');}
function showOrders(){openModal('LỊCH SỬ TRÊN TRÌNH DUYỆT NÀY',`<div class="modal-body-pad"><h2 id="modal-title">Đơn hàng thử của tôi</h2><p>Đây là lịch sử đơn mô phỏng. Không đồng bộ giữa các thiết bị.</p>${state.orders.length?[...state.orders].reverse().map(o=>`<article class="order-list-item"><div><b>${escapeHTML(o.id)}</b><span class="status-pill">Đơn mô phỏng</span></div><small>${new Date(o.date).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'})}</small><p>${escapeHTML(o.name)} · ${escapeHTML(o.phone)}</p><p>${(o.items||[]).map(i=>`${escapeHTML(findProduct(i.id)?.name||'Sản phẩm')} × ${Number(i.qty)||0}`).join(' · ')}</p><div><span>Tạm tính</span><strong>${money(Number(o.total)||0)}</strong></div></article>`).join(''):'<div class="empty-state"><span data-icon="bag"></span><h3>Chưa có đơn hàng thử</h3><p>Thêm sản phẩm vào giỏ và hoàn tất bước đặt hàng để xem kết quả tại đây.</p><button class="button button-pink" data-action="continue-shopping">Khám phá sản phẩm</button></div>'}</div>`,'orders');}
const policyContent={
 shipping:{title:'Giao hàng & kiểm hàng',text:'Bản thiết kế có khối Freeship nhưng chưa ghi điều kiện áp dụng. Bản thử vì vậy chỉ tính tiền sản phẩm, chưa tính phí giao hàng.',items:['Cần xác nhận khu vực giao hàng, đơn vị vận chuyển và thời gian dự kiến.','Cần cung cấp mức phí, ngưỡng miễn phí và các ngoại lệ.','Cần quy định việc kiểm hàng, tình trạng bao bì và xử lý hàng hư hỏng.']},
 warranty:{title:'Bảo hành & đổi trả',text:'Bản thiết kế có nút bảo hành nhưng chưa cung cấp nội dung chính sách. Những điều kiện dưới đây là danh mục cần hoàn thiện, chưa phải cam kết của Louis Yoga.',items:['Xác định thời hạn và phạm vi bảo hành theo từng dòng sản phẩm.','Nêu điều kiện đổi trả, chứng từ cần có và trường hợp không áp dụng.','Bổ sung biểu mẫu tra cứu hoặc gửi yêu cầu gắn với mã đơn thật.']},
 privacy:{title:'Bảo mật thông tin',text:'Trong bản trải nghiệm này, giỏ hàng, sản phẩm yêu thích, đơn thử, email nhận tin và phiếu quan tâm chỉ được lưu bằng localStorage trên trình duyệt. Không có đăng nhập hoặc máy chủ nhận biểu mẫu.',items:['Có thể xóa dữ liệu thử trong mục Ghi chú thiết kế.','Dữ liệu không đồng bộ giữa các trình duyệt hoặc thiết bị.','Khi đưa vào vận hành thật cần bổ sung chính sách bảo mật, thời hạn lưu trữ và cơ chế đồng ý theo hệ thống được triển khai.']},
 terms:{title:'Điều khoản & quy định',text:'Đây là prototype để xem và đánh giá thiết kế. Mọi thao tác mua, đặt hàng và đăng ký là mô phỏng; chưa tạo giao dịch thương mại.',items:['Chưa có phí vận chuyển, thuế bổ sung hoặc xử lý thanh toán.','Không dùng số lượng và giá mẫu để cam kết với khách hàng.','Nội dung điều khoản thương mại phải được Louis Yoga xác nhận trước khi xuất bản website bán hàng thật.']},
 ctv:{title:'Cộng tác viên & đại lý',text:'Bản thiết kế đề xuất chương trình cộng tác viên và đại lý, nhưng chưa có cơ chế hoặc điều kiện cụ thể.',items:['Cần xác nhận điều kiện tham gia và cách xét duyệt.','Cần quy định giá, chiết khấu, thanh toán và trách nhiệm của các bên.','Biểu mẫu trong bản thử chỉ lưu phiếu quan tâm cục bộ, không gửi hồ sơ thật.']}
};
function showPolicy(kind){const p=policyContent[kind]||policyContent.terms;openModal('THÔNG TIN CẦN HOÀN THIỆN',`<div class="modal-body-pad"><h2 id="modal-title">${p.title}</h2><div class="demo-notice">Nội dung phục vụ đánh giá thiết kế, chưa phải chính sách kinh doanh được duyệt.</div><p>${p.text}</p><h3>Phần cần bổ sung trước khi vận hành</h3><ul>${p.items.map(v=>`<li>${v}</li>`).join('')}</ul><h3>Thông tin hỗ trợ trong file thiết kế</h3><p>Hotline: 0973.168.389<br>Email: louisyogamat@gmail.com<br>Cần đối chiếu lại trước khi website hoạt động chính thức.</p>${kind==='ctv'?'<button class="button button-pink" data-action="interest" data-kind="ctv">Thử phiếu quan tâm</button>':''}</div>`,'policy');}
function showInterest(kind){const course=kind==='course';openModal('KẾT NỐI · BIỂU MẪU MÔ PHỎNG',`<div class="modal-body-pad"><h2 id="modal-title">${course?'Quan tâm khóa học yoga':'Đăng ký cộng tác viên'}</h2><p>${course?'Đề xuất một bước để người quan tâm để lại nhu cầu trước khi có danh sách khóa học.':'Đề xuất thu thập nhu cầu hợp tác trước khi có quy trình xét duyệt cộng tác viên.'}</p><div class="demo-notice">Phiếu chỉ lưu trên trình duyệt, chưa gửi đến Louis Yoga. Có thể nhập dữ liệu giả để thử.</div><form id="interest-form" data-kind="${course?'course':'ctv'}"><div class="form-grid"><label class="field">Họ và tên *<input name="name" required maxlength="80" placeholder="Tên của bạn"></label><label class="field">Email *<input name="email" type="email" required maxlength="120" placeholder="email@example.com"></label><label class="field wide">${course?'Nhu cầu học':'Hình thức quan tâm'}<select name="goal">${(course?['Mới bắt đầu','Đã tập và muốn tìm hiểu thêm','Muốn biết lịch và học phí']:['Cộng tác viên bán hàng','Đại lý / cửa hàng','Hợp tác nội dung']).map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field wide">Nội dung quan tâm<textarea name="note" maxlength="300" placeholder="Chia sẻ thêm nhu cầu (không bắt buộc)"></textarea></label></div><label class="check-field"><input name="consent" type="checkbox" required><span>Tôi đồng ý lưu phiếu thử trên trình duyệt này.</span></label><p class="form-error" id="interest-error" role="alert"></p><div class="form-actions"><button class="button button-pink" type="submit">Lưu phiếu quan tâm thử ${icon('arrow-right')}</button></div></form></div>`,'interest');}
function handleInterest(form){const f=new FormData(form);const name=String(f.get('name')||'').trim();if(!name){$('#interest-error').textContent='Vui lòng nhập họ và tên có nội dung.';return;}state.interests.push({kind:form.dataset.kind,name,email:String(f.get('email')).trim(),goal:String(f.get('goal')),note:String(f.get('note')||'').trim(),date:new Date().toISOString()});state.interests=state.interests.slice(-30);save();openModal('BIỂU MẪU MÔ PHỎNG',`<div class="success-view"><span class="success-icon">${icon('check')}</span><h2 id="modal-title">Đã lưu phiếu quan tâm thử</h2><p>Phiếu của ${escapeHTML(name)} được lưu trên trình duyệt này. Chưa gửi thông báo hoặc yêu cầu đến Louis Yoga.</p><button class="button button-pink" data-action="close-modal">Tiếp tục khám phá</button></div>`,'interest-success');}
const quizQuestions=[{title:'Bạn ưu tiên điều gì khi chọn thảm?',desc:'Chọn một nhu cầu để thử cách tư vấn sản phẩm.',options:[['portable','Dễ mang theo','Thường mang thảm đến nơi tập'],['home','Một góc tập tại nhà','Thường sử dụng cố định'],['look','Màu sắc & phong cách','Muốn phối với không gian tập']]},{title:'Khoảng giá bạn muốn tham khảo?',desc:'Các khoảng giá đều dựa trên dữ liệu mẫu trong prototype.',options:[['low','Dưới 500.000 đ','Khám phá nhóm TPE mẫu'],['mid','500.000–800.000 đ','Khám phá nhóm cao su mẫu'],['high','Trên 800.000 đ','Khám phá nhóm cao cấp mẫu']]},{title:'Tông màu nào hợp với bạn?',desc:'Có thể đổi màu khi xem chi tiết sản phẩm.',options:[['rose','Hồng phấn','Nhẹ nhàng & ấm áp'],['sage','Xanh sage','Trung tính & tự nhiên'],['plum','Đỏ rượu','Đậm nét & nổi bật']]}];
function startQuiz(){quizStep=0;quizAnswers=[];renderQuiz();}
function renderQuiz(){if(quizStep>=3){showRecommendation();return;}const q=quizQuestions[quizStep];openModal('TÌM THẢM PHÙ HỢP · ĐỀ XUẤT CHỨC NĂNG',`<div class="modal-body-pad"><div class="quiz-progress">CÂU HỎI ${quizStep+1} / 3</div><h2 id="modal-title">${q.title}</h2><p>${q.desc}</p><div class="quiz-options">${q.options.map((o,n)=>`<button class="quiz-option" data-action="quiz-answer" data-answer="${o[0]}"><span>0${n+1}</span><span><b>${o[1]}</b><small>${o[2]}</small></span><span style="margin-left:auto">${icon('arrow-right')}</span></button>`).join('')}</div>${quizStep?'<button class="quiz-back" data-action="quiz-back">← Quay lại câu trước</button>':''}</div>`,'quiz');}
function showRecommendation(){const color=quizAnswers[2]||'rose';const id=quizAnswers[1]==='low'?(color==='rose'?'tpe-rose':'tpe-lavender'):quizAnswers[1]==='high'?'premium-cacao':color==='sage'?'rubber-sage':color==='rose'?'rubber-rose':'lilium';const p=findProduct(id);openModal('GỢI Ý TỪ BỘ SƯU TẬP MẪU',`<div class="modal-body-pad"><span class="quiz-progress">ĐÃ HOÀN THÀNH 3 CÂU HỎI</span><h2 id="modal-title">Một lựa chọn để bắt đầu</h2><p>Gợi ý ưu tiên khoảng giá và tông màu bạn vừa chọn. Khi có thông số thật, bước tư vấn có thể bổ sung trọng lượng và chất liệu phù hợp nhu cầu ${quizAnswers[0]==='portable'?'mang theo':quizAnswers[0]==='home'?'tập tại nhà':'phối màu'}.</p><div class="recommendation"><img src="${imageFor(p,color)}" alt="Minh họa thảm được gợi ý"><div><b>${p.name}</b><p>${money(p.price)} · Giá mẫu</p><button class="button button-pink" data-action="quiz-detail" data-id="${p.id}" data-color="${color}">Xem lựa chọn ${icon('arrow-right')}</button></div></div><div class="demo-notice">Đây là cách hoạt động đề xuất cho công cụ chọn thảm. Chưa phải đánh giá chất lượng hoặc tư vấn dựa trên thông số sản phẩm thật.</div><button class="quiz-back" data-action="quiz">Làm lại từ đầu</button></div>`,'quiz-result');}
const stories={
 journey:{title:'Hành trình trên thảm',intro:'Đề xuất một khối nội dung kể chuyện bằng hình ảnh thật của Louis Yoga: góc tập, sản phẩm đang sử dụng và hành trình của người tập.',points:['Mở đầu bằng một câu chuyện cụ thể, có người và bối cảnh đã xác nhận.','Liên kết đến chiếc thảm hoặc phụ kiện xuất hiện trong nội dung.','Có phụ đề cho video và bản tóm tắt chữ để dễ tiếp cận.'],note:'Thiết kế hiện chỉ có khung video, chưa có tệp hoặc đường dẫn. Prototype dùng minh họa tĩnh để thể hiện vị trí và bố cục.'},
 care:{title:'Giữ góc tập luôn sẵn sàng',intro:'Khung bài viết đề xuất về cách chăm sóc thảm. Hướng dẫn chi tiết phải căn cứ vào vật liệu và hướng dẫn của nhà sản xuất từng dòng sản phẩm.',points:['Tách hướng dẫn theo cao su, TPE và các bề mặt khác.','Bổ sung ảnh từng bước và các thao tác cần tránh đã được nhà sản xuất xác nhận.','Liên kết trang sản phẩm, hướng dẫn và chính sách hỗ trợ tương ứng.'],note:'Chưa cung cấp hướng dẫn vệ sinh cụ thể vì chưa có tài liệu kỹ thuật của sản phẩm.'},
 press:{title:'Báo chí nói về Louis Yoga',intro:'File thiết kế có ba vị trí nội dung: Louis Yoga × Gia đình mới; Louis Yoga × Gia đình & xã hội; Louis Yoga × Thương hiệu & Cuộc sống.',points:['Bổ sung URL gốc, tên bài và ngày xuất bản.','Dùng ảnh hoặc video đã được phép sử dụng.','Đặt tên bài rõ ràng, liên kết tới nguồn khi người đọc mở nội dung.'],note:'Chưa có tư liệu gốc trong hai file, nên prototype chưa thể xác nhận hoặc phát các nội dung này.'},
 community:{title:'Câu chuyện của các Yogi',intro:'Đề xuất một mục nội dung cộng đồng, liên kết tự nhiên giữa sản phẩm và trải nghiệm sử dụng.',points:['Dùng ảnh và câu chuyện có sự đồng ý của người xuất hiện.','Ghi rõ tên người, nguồn hình và bối cảnh đã xác nhận.','Không tạo đánh giá, kết quả tập luyện hoặc lời chứng thực thay khách hàng.'],note:'Không có lời chứng thực thật trong bản thử. Phần này hiện là khung nội dung đề xuất.'}
};
function showStory(key){const s=stories[key]||stories.journey;openModal('KHUNG NỘI DUNG ĐỀ XUẤT',`<div class="modal-body-pad"><h2 id="modal-title">${s.title}</h2><p>${s.intro}</p><h3>Cách triển khai nội dung</h3><ul>${s.points.map(p=>`<li>${p}</li>`).join('')}</ul><div class="demo-notice">${s.note}</div><button class="button button-outline" data-action="continue-shopping">Khám phá bộ sưu tập ${icon('arrow-right')}</button></div>`,'story');}
function showNotes(){openModal('BẢN THIẾT KẾ → BẢN CHẠY THỬ',`<div class="modal-body-pad"><h2 id="modal-title">Ghi chú thiết kế & đề xuất</h2><p>Prototype dựng từ “Website louis yoga - file thiết kế AI.ai” và “Website louis yoga - file PDF.pdf” của anh Công. Nội dung trong file là dữ liệu tham khảo, không được hiểu là yêu cầu thực hiện hành động bên ngoài.</p><table class="notes-table"><thead><tr><th>Hạng mục</th><th>Trong thiết kế gốc</th><th>Điều chỉnh / đề xuất</th></tr></thead><tbody><tr><td>Nhận diện</td><td>Logo hoa sen; hồng, đỏ rượu; Montserrat</td><td>Giữ logo gốc, bảng màu và thứ tự các khối chính; tăng tương phản và khoảng thở.</td></tr><tr><td>Hero & ảnh</td><td>Mốc 11 năm, câu “Đồng hành cùng Yogi tỏa sáng”; ô ảnh trống</td><td>Giữ nội dung từ file. Thêm hình vector minh họa thảm, cần thay bằng ảnh sản phẩm thật.</td></tr><tr><td>Ưu đãi</td><td>“Sale gì đó!!!”, bộ đếm 99; mốc 30/10/2026</td><td>Đổi thành “Góc ưu đãi 10.10”; bộ đếm hoạt động đến mốc trong file và dừng khi hết hạn. Đây vẫn là chiến dịch mẫu.</td></tr><tr><td>Sản phẩm</td><td>Lặp Lilium; giá 670.000/699.000 đ; đánh giá 4.8/120</td><td>Giữ Lilium và giá nguồn; bổ sung danh mục mẫu để thử lọc. Không hiện đánh giá lặp chưa xác minh.</td></tr><tr><td>Mua hàng</td><td>Nút thêm giỏ và mua ngay</td><td>Tìm kiếm, lọc/sắp xếp, màu, yêu thích, giỏ và đơn thử có lịch sử cục bộ. Chưa có thanh toán thật.</td></tr><tr><td>CTV / khóa học</td><td>Hai banner, chưa có nội dung chi tiết</td><td>Biểu mẫu quan tâm mẫu; chờ điều kiện, lịch, học phí và quy trình thật.</td></tr><tr><td>Truyền thông</td><td>Khung video, tên ba bài báo</td><td>Khung bài viết đọc được; không giả lập video hay nguồn báo chưa có.</td></tr><tr><td>Điện thoại</td><td>Một bố cục desktop</td><td>Menu gọn, thẻ sản phẩm 2 cột, modal và giỏ hàng phù hợp màn hình nhỏ.</td></tr></tbody></table><h3>Hai hướng triển khai</h3><p><strong>Khuyến nghị — Cửa hàng tinh gọn:</strong> tập trung danh mục, chi tiết, giỏ hàng, thanh toán, giao hàng và hỗ trợ. Hoàn thiện ảnh, SKU, tồn kho và chính sách trước khi mở bán.</p><p><strong>Giai đoạn sau — Cộng đồng & khóa học:</strong> thêm lịch học, nội dung video, tài khoản hoặc CTV khi có người phụ trách và quy trình vận hành. Hướng này cần thêm dữ liệu và công quản trị.</p><h3>Trạng thái dữ liệu</h3><p>Giá, ảnh vector, kích thước, biến thể và tên sản phẩm bổ sung đều là mẫu. Mốc 11 năm, tên Lilium và thông tin liên hệ được chép từ file, chưa được kiểm chứng độc lập. Các biểu mẫu không gửi dữ liệu ra ngoài.</p><div class="demo-notice">${storageAvailable?'Giỏ, yêu thích, đơn thử và phiếu đăng ký được lưu trên trình duyệt này.':'Trình duyệt chưa cho phép lưu dữ liệu; bản thử hoạt động trong phiên hiện tại.'} Có thể xóa toàn bộ dữ liệu thử bằng nút dưới đây.</div><button class="button button-outline" data-action="clear-data">Xóa dữ liệu thử trên trình duyệt</button></div>`,'notes');}
function countdown(){const end=new Date('2026-10-30T23:59:59+07:00').getTime();const seconds=Math.max(0,Math.floor((end-Date.now())/1000));if(!seconds){$('#countdown').innerHTML='<span style="font-size:10px;color:#946077">Đã kết thúc mốc minh họa</span>';return;}const units=[[Math.floor(seconds/86400),'Ngày'],[Math.floor(seconds/3600)%24,'Giờ'],[Math.floor(seconds/60)%60,'Phút'],[seconds%60,'Giây']];$('#countdown').innerHTML=units.map(([n,label])=>`<span class="time-cell"><b>${String(n).padStart(2,'0')}</b><small>${label}</small></span>`).join('');}
document.addEventListener('click',e=>{
 const a=e.target.closest('[data-action]');if(!a)return;e.preventDefault();const action=a.dataset.action,id=a.dataset.id;
 switch(action){
  case 'notes':showNotes();break;case 'search':showSearch();break;case 'favorites':showFavorites();break;case 'favorite':favorite(id);break;case 'orders':showOrders();break;
  case 'detail':showDetail(id);break;case 'add':addToCart(id);break;case 'buy':if(addToCart(id,null,1,false))showCheckout();break;
  case 'cart':openCart();break;case 'close-cart':closeCart();break;case 'close-modal':closeModal();break;
  case 'continue-shopping':closeCart();closeModal();$('#tham').scrollIntoView({behavior:'smooth'});break;
  case 'cart-minus':cartQty(a.dataset.key,-1);break;case 'cart-plus':cartQty(a.dataset.key,1);break;
  case 'remove':state.cart=state.cart.filter(i=>i.key!==a.dataset.key);save();updateCounts();renderCart();toast('Đã xóa sản phẩm khỏi giỏ.');break;
  case 'checkout':showCheckout();break;
  case 'detail-color':detailColor=a.dataset.color;renderDetail();break;
  case 'detail-minus':detailQty=Math.max(1,detailQty-1);renderDetail();break;case 'detail-plus':detailQty=Math.min(10,detailQty+1);renderDetail();break;
  case 'detail-add':if(addToCart(detailProduct.id,detailColor,detailQty,false))openCart();break;
  case 'detail-buy':if(addToCart(detailProduct.id,detailColor,detailQty,false))showCheckout();break;
  case 'accessories-prev':accessoryPage=(accessoryPage+1)%2;renderAccessories();break;case 'accessories-next':accessoryPage=(accessoryPage+1)%2;renderAccessories();break;case 'accessory-page':accessoryPage=Number(a.dataset.page);renderAccessories();break;
  case 'policy':showPolicy(a.dataset.kind);break;case 'interest':showInterest(a.dataset.kind);break;case 'story':showStory(a.dataset.story);break;
  case 'quiz':startQuiz();break;case 'quiz-answer':quizAnswers[quizStep]=a.dataset.answer;quizStep++;renderQuiz();break;case 'quiz-back':quizStep=Math.max(0,quizStep-1);renderQuiz();break;
  case 'quiz-detail':showDetail(id);detailColor=a.dataset.color;renderDetail();break;
  case 'top':window.scrollTo({top:0,behavior:'smooth'});break;
  case 'menu':{const nav=$('#mobile-nav');nav.hidden=!nav.hidden;a.setAttribute('aria-expanded',String(!nav.hidden));break;}
  case 'clear-data':state={cart:[],favorites:[],orders:[],interests:[],newsletter:[]};save();updateCounts();renderFavoritesState();showNotes();toast('Đã xóa toàn bộ dữ liệu thử trên trình duyệt này.');break;
 }
});
document.addEventListener('click',e=>{const tab=e.target.closest('[data-filter]');if(tab)setFilter(tab.dataset.filter);const link=e.target.closest('[data-filter-link]');if(link){setFilter(link.dataset.filterLink);$('#shop-menu').hidden=true;$('.nav-trigger').setAttribute('aria-expanded','false');}if(e.target.closest('#mobile-nav a')){$('#mobile-nav').hidden=true;$('[data-action=menu]').setAttribute('aria-expanded','false');}const trigger=e.target.closest('.nav-trigger');if(trigger){const menu=$('#shop-menu');menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));}else if(!e.target.closest('.nav-dropdown')){$('#shop-menu').hidden=true;$('.nav-trigger').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{const tabButton=e.target.closest('[data-filter]');if(tabButton&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-filter]')];const index=tabs.indexOf(tabButton);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setFilter(tabs[next].dataset.filter);tabs[next].focus();}if(e.key==='Escape'){if(!$('#cart-drawer').hidden)closeCart();$('#shop-menu').hidden=true;$('.nav-trigger').setAttribute('aria-expanded','false');$('#mobile-nav').hidden=true;$('[data-action=menu]').setAttribute('aria-expanded','false');}if(e.key==='Tab'&&!$('#cart-drawer').hidden){const focusable=[...$('#cart-drawer').querySelectorAll('button:not(:disabled),a,input,select,textarea')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('input',e=>{if(e.target.id==='search-input')searchProducts(e.target.value);});
$('#product-sort').addEventListener('change',e=>{sort=e.target.value;renderMats();});
document.addEventListener('submit',e=>{if(e.target.id==='checkout-form'){e.preventDefault();handleCheckout(e.target);}if(e.target.id==='interest-form'){e.preventDefault();handleInterest(e.target);}if(e.target.id==='newsletter-form'){e.preventDefault();const email=$('#newsletter-email').value.trim().toLowerCase();if(state.newsletter.includes(email)){$('#newsletter-status').textContent='Email này đã có trong danh sách thử trên trình duyệt.';return;}state.newsletter.push(email);state.newsletter=state.newsletter.slice(-30);save();$('#newsletter-status').textContent='Đã lưu email trong bản thử. Chưa đăng ký vào hệ thống nhận tin thật.';e.target.reset();}});
window.addEventListener('scroll',()=>{$('[data-action=top]').hidden=window.scrollY<700;},{passive:true});
$('#sale-products').innerHTML=['lilium','tpe-rose','premium-cacao','block'].map(id=>card(findProduct(id))).join('');
hydrateIcons();renderMats();renderAccessories();updateCounts();countdown();setInterval(countdown,1000);
